from fractions import Fraction

def _fact(k):
    r = 1
    for i in range(2, k + 1):
        r *= i
    return r

def verify(witness):
    lo, hi = witness['n_range']
    nlo, nhi = witness['N_range']
    if lo < 2:
        raise ValueError('n=1 excluded: 0!-1 = 0 gives zero denominator')
    if nlo < 1:
        raise ValueError('N must start at 1')
    for n in range(lo, hi + 1):
        f = _fact(n)
        d = f - 1
        if d == 0:
            raise ValueError('zero denominator at n=%d' % n)
        base = Fraction(1, d)
        for N in range(nlo, nhi + 1):
            s_n = Fraction(0)
            p = Fraction(1, f)
            for j in range(1, N + 1):
                s_n += p
                p = p / f
            residual = Fraction(1, (f ** N) * d)
            if base != s_n + residual:
                raise AssertionError('identity violated at n=%d N=%d' % (n, N))
    return True
